      ko: '여러 사람이나 사물, 장소, 음식처럼 하나의 집단이나 범위가 있을 때 그 안에서 하나를 고르거나 비교할 때 사용해요. "중에"와 "중에서"는 대부분 비슷하게 사용할 수 있지만, "중에서"는 어떤 범위 안에서 선택하거나 비교한다는 느낌을 조금 더 분명하게 나타내요.',
      uz: 'Bir nechta odam, narsa, joy yoki taomdan iborat guruh ichidan bittasini tanlash yoki ularni o‘zaro taqqoslashda ishlatiladi. "중에" va "중에서" ko‘p vaziyatlarda bir xil ma’noda ishlatiladi, ammo "중에서" ma’lum bir guruh ichidan tanlash yoki solishtirish ma’nosini biroz aniqroq ko‘rsatadi.',
      en: 'Used when choosing or comparing one item within a group or range of people, things, places, foods, and so on. 중에 and 중에서 are often interchangeable, although 중에서 makes the idea of selecting or comparing within a specific group slightly more explicit.',
