    explanation: {
      ko: '"N 중에(서)"는 여러 대상이 이루는 범위를 먼저 제시하고, 그 범위 안에서 어떤 대상을 선택하거나 비교할 때 사용하는 표현이에요. 여기서 "중"은 "여럿 가운데"라는 뜻을 나타내요. 예를 들어 "한식 중에서 비빔밥을 제일 좋아해요."라고 하면 한식이라는 큰 범위를 먼저 정한 뒤, 그 안에 있는 여러 음식 가운데 비빔밥을 가장 좋아한다는 뜻이에요. "비빔밥하고 불고기 중에 뭐 먹을래요?"처럼 두 가지 이상의 선택지를 직접 나열한 뒤 사용할 수도 있어요. 사람을 고를 때는 "친구들 중에서 누구하고 제일 친해요?", 장소를 비교할 때는 "이 식당들 중에 어디가 제일 맛있어요?"처럼 사용할 수 있어요. 따라서 이 문법은 "뭐", "누구", "어디", "어느 것" 같은 의문사와 아주 자주 함께 사용되고, "가장", "제일"처럼 최고 정도를 나타내는 표현과도 자주 어울려요. "중에"와 "중에서"는 실제 대화에서 의미 차이가 크지 않은 경우가 많아요. "세 메뉴 중에 뭐가 제일 맛있어요?"와 "세 메뉴 중에서 뭐가 제일 맛있어요?"는 모두 자연스러워요. 다만 "중에서"는 앞에서 제시한 집단을 하나의 선택 범위로 조금 더 분명하게 느끼게 해요. 중요한 것은 "중에(서)" 앞에 반드시 선택이나 비교의 범위가 되는 명사나 명사 표현이 온다는 점이에요. "둘 중에", "세 가지 중에서", "우리 반 학생들 중에", "한국 음식 중에서"처럼 사용할 수 있어요.',
      uz: '"N 중에(서)" bir nechta narsadan tashkil topgan guruh yoki doirani avval belgilab, so‘ng shu guruh ichidan biror narsani tanlash yoki solishtirish uchun ishlatiladi. Bu yerda "중" "bir nechtasi orasida" degan ma’noni beradi. Masalan, "한식 중에서 비빔밥을 제일 좋아해요." gapida avval koreys taomlari umumiy guruh sifatida belgilanadi, keyin shu taomlar orasida bibimbap eng yoqimli taom ekanligi aytiladi. Ikki yoki undan ortiq variantni bevosita sanab ham ishlatish mumkin: "비빔밥하고 불고기 중에 뭐 먹을래요?" — "Bibimbap bilan bulgogidan qaysi birini yeysiz?" Odamlar bilan "친구들 중에서 누구하고 제일 친해요?", joylar bilan esa "이 식당들 중에 어디가 제일 맛있어요?" kabi ishlatiladi. Shu sababli bu grammatika "뭐", "누구", "어디", "어느 것" kabi so‘roq so‘zlari hamda "가장", "제일" kabi eng yuqori darajani bildiruvchi so‘zlar bilan ko‘p uchraydi. "중에" va "중에서" kundalik nutqda ko‘pincha deyarli bir xil ma’noda ishlatiladi. Ammo "중에서" aynan ko‘rsatilgan guruh ichidan tanlash yoki solishtirish ma’nosini biroz kuchliroq ko‘rsatadi. "중에(서)"dan oldin tanlash yoki taqqoslash doirasini bildiruvchi ot yoki ot birikmasi kelishi kerak: "둘 중에", "세 가지 중에서", "우리 반 학생들 중에", "한국 음식 중에서" kabi.',
      en: '"N 중에(서)" first establishes a group or range and then selects or compares something within that range. Here, 중 carries the meaning of "among" or "in the group of." For example, in "한식 중에서 비빔밥을 제일 좋아해요.", Korean food is established as the overall category, and bibimbap is then selected as the speaker\'s favorite within that category. You can also list two or more choices directly, as in "비빔밥하고 불고기 중에 뭐 먹을래요?" It works with people in sentences such as "친구들 중에서 누구하고 제일 친해요?" and with places in sentences such as "이 식당들 중에 어디가 제일 맛있어요?" Because it establishes a set of choices, this grammar frequently appears with question words such as 뭐, 누구, 어디, and 어느 것, and with superlative expressions such as 가장 and 제일. In everyday Korean, 중에 and 중에서 are often very close in meaning. Both "세 메뉴 중에 뭐가 제일 맛있어요?" and "세 메뉴 중에서 뭐가 제일 맛있어요?" are natural. 중에서 simply makes the idea of selecting from the stated group a little more explicit. The expression before 중에(서) must provide the group or range being considered, such as "둘 중에", "세 가지 중에서", "우리 반 학생들 중에", or "한국 음식 중에서".',
      ru: '"N 중에(서)" сначала задаёт группу или диапазон, а затем позволяет выбрать или сравнить что-либо внутри этой группы. Слово 중 здесь имеет значение «среди» или «из числа». Например, в предложении "한식 중에서 비빔밥을 제일 좋아해요." сначала задаётся категория корейских блюд, а затем говорящий сообщает, что среди них больше всего любит пибимпап. Можно также непосредственно перечислить два или несколько вариантов: "비빔밥하고 불고기 중에 뭐 먹을래요?" Конструкция употребляется с людьми — "친구들 중에서 누구하고 제일 친해요?", с местами — "이 식당들 중에 어디가 제일 맛있어요?" и со многими другими группами. Поэтому она часто встречается вместе с вопросительными словами 뭐, 누구, 어디, 어느 것 и со словами превосходной степени 가장 и 제일. В повседневной речи 중에 и 중에서 во многих случаях почти одинаковы. Предложения "세 메뉴 중에 뭐가 제일 맛있어요?" и "세 메뉴 중에서 뭐가 제일 맛있어요?" оба естественны. 중에서 лишь немного яснее подчёркивает выбор именно внутри указанной группы. Перед 중에(서) должна находиться группа или диапазон для выбора или сравнения: "둘 중에", "세 가지 중에서", "우리 반 학생들 중에", "한국 음식 중에서".',
    },

