      pattern: "'ㅅ' 불규칙 ↔ 'ㅅ' 규칙 활용",
      note: {
        ko: "'ㅅ' 받침이 있다고 해서 모두 불규칙하게 활용하는 것은 아니에요. '낫다, 짓다, 붓다, 긋다, 젓다, 잇다'처럼 일부 단어는 모음으로 시작하는 어미 앞에서 ㅅ이 없어지지만, '웃다, 씻다, 벗다'처럼 규칙적으로 활용하는 단어는 ㅅ을 그대로 유지해요. 따라서 '낫다 → 나아요'와 '웃다 → 웃어요'를 함께 비교해서 익히는 것이 좋아요.",
        uz: "Oxiri 'ㅅ' bilan tugagan barcha so‘zlar noto‘g‘ri tuslanmaydi. '낫다, 짓다, 붓다, 긋다, 젓다, 잇다' kabi ayrim so‘zlarda unli bilan boshlanuvchi qo‘shimcha oldidan ㅅ tushadi, ammo '웃다, 씻다, 벗다' kabi muntazam fe’llarda ㅅ saqlanadi. Shuning uchun '낫다 → 나아요' va '웃다 → 웃어요' kabi shakllarni taqqoslab o‘rganish foydali.",
        en: 'Not every ㅅ-final word is irregular. Words such as 낫다, 짓다, 붓다, 긋다, 젓다, and 잇다 drop ㅅ before vowel-initial endings, while regular verbs such as 웃다, 씻다, and 벗다 keep it. Comparing forms such as 낫다 → 나아요 with 웃다 → 웃어요 is therefore especially helpful.',
        ru: 'Не каждое слово с 받침 ㅅ относится к неправильному типу. В словах 낫다, 짓다, 붓다, 긋다, 젓다 и 잇다 ㅅ исчезает перед окончанием на гласную, а правильные глаголы 웃다, 씻다 и 벗다 сохраняют его. Полезно сравнивать такие пары, как 낫다 → 나아요 и 웃다 → 웃어요.',
      },
