    similar: {
      pattern: 'N마다 ↔ 매 N',
      note: {
        ko: '"N마다"와 "매 N"은 반복되는 시간을 나타낼 때 비슷하게 사용할 수 있어요. 예를 들어 "주말마다 운동해요"와 "매주 운동해요"는 모두 정기적으로 운동한다는 뜻이에요. 하지만 "마다"는 시간뿐 아니라 사람·장소·사물 하나하나에도 사용할 수 있어요. "사람마다 생각이 달라요", "병원마다 시간이 달라요"는 자연스럽지만, 이런 경우 단순히 "매 사람", "매 병원"이라고 바꾸면 매우 어색해요. 따라서 반복되는 시간에서는 둘이 비슷할 수 있지만, 각각의 구성원이나 개별적인 차이를 강조할 때는 "마다"가 훨씬 넓게 사용돼요.',
        uz: '"N마다" va "매 N" takrorlanadigan vaqtni bildirishda o‘xshash bo‘lishi mumkin. Masalan, "주말마다 운동해요" va "매주 운동해요" ikkalasi ham muntazam sport qilishni anglatadi. Ammo "마다" odam, joy va narsalarning har biriga ham qo‘llanadi. "사람마다 생각이 달라요", "병원마다 시간이 달라요" tabiiy, lekin bularni oddiygina "매 사람", "매 병원" deb aytish juda g‘alati.',
        en: '"N마다" and "매 N" can overlap when talking about recurring times. For example, "주말마다 운동해요" and "매주 운동해요" both describe regular exercise. However, 마다 can also refer to each individual person, place, or thing. Expressions such as "사람마다 생각이 달라요" and "병원마다 시간이 달라요" are natural, whereas simply replacing them with "매 사람" or "매 병원" would sound very unnatural.',
        ru: '"N마다" и "매 N" могут быть похожи при обозначении повторяющегося времени. Например, "주말마다 운동해요" и "매주 운동해요" оба говорят о регулярных тренировках. Однако 마다 также употребляется с каждым отдельным человеком, местом или предметом. Фразы "사람마다 생각이 달라요" и "병원마다 시간이 달라요" естественны, а замена на "매 사람" или "매 병원" звучит неестественно.',
      },
    },

