    isActive: true,

    summary: {
      ko: '"V-는 게 어때요?"는 상대방에게 어떤 행동을 해 보는 것이 좋겠다고 부드럽게 권하거나 제안할 때 사용하는 표현이에요. 명령처럼 강하게 말하지 않고 상대방의 선택을 존중하면서 의견을 제시할 수 있어서 일상 대화에서 아주 자주 사용해요.',
      uz: '"V-는 게 어때요?" suhbatdoshga biror ishni qilishni muloyim tarzda tavsiya qilish yoki taklif etishda ishlatiladi. Bu buyruq kabi kuchli emas va suhbatdoshning tanlovini hurmat qilgan holda maslahat berishga imkon beradi.',
      en: '"V-는 게 어때요?" is used to gently suggest or recommend that someone do something. It is softer than a command and allows the speaker to offer an idea while leaving the decision to the listener.',
      ru: '"V-는 게 어때요?" используется, чтобы мягко предложить или посоветовать собеседнику что-либо сделать. Эта форма звучит мягче приказа и оставляет окончательное решение за собеседником.',
    },

