    similar: {
      pattern: 'V-는 게 어때요? ↔ V-(으)세요',
      note: {
        ko: '"V-는 게 어때요?"와 "V-(으)세요"는 모두 상대방에게 어떤 행동을 하도록 말할 때 사용할 수 있지만 말하는 느낌이 달라요. "운동하세요."는 상대방에게 직접 행동을 권하거나 지시하는 표현이에요. 반면 "운동하는 게 어때요?"는 "운동을 해 보면 어떨까요?"처럼 하나의 선택지를 제안하기 때문에 더 부드럽고 상대방의 판단을 존중하는 느낌이 있어요. 특히 친구나 동료에게 조언을 하거나 상대방이 받아들일지 확실하지 않은 상황에서는 "V-는 게 어때요?"가 자연스러워요.',
        uz: '"V-는 게 어때요?" va "V-(으)세요" ikkalasi ham suhbatdoshga biror ishni qilish haqida aytishda ishlatilishi mumkin, lekin ohangi farq qiladi. "운동하세요." to‘g‘ridan-to‘g‘ri tavsiya yoki ko‘rsatma beradi. "운동하는 게 어때요?" esa bir variant sifatida taklif qiladi va suhbatdoshning qarorini ko‘proq hurmat qiladi.',
        en: '"V-는 게 어때요?" and "V-(으)세요" can both encourage someone to take an action, but their tone differs. "운동하세요." directly recommends or instructs the listener to exercise. "운동하는 게 어때요?" presents exercise as an option and therefore sounds softer and more respectful of the listener\'s choice.',
        ru: '"V-는 게 어때요?" и "V-(으)세요" могут побуждать собеседника к действию, но отличаются по тону. "운동하세요." является более прямым советом или указанием. "운동하는 게 어때요?" предлагает действие как один из вариантов и звучит мягче, оставляя решение собеседнику.',
      },
    },

