        uz: '❌ "운동하다는 게 어때요?" deyilmaydi. "-다" olib tashlanib ✅ "운동하는 게 어때요?" ishlatiladi.',
        en: '❌ Do not say "운동하다는 게 어때요?" Remove -다 and use ✅ "운동하는 게 어때요?"',
        ru: '❌ Нельзя говорить "운동하다는 게 어때요?". Нужно убрать -다: ✅ "운동하는 게 어때요?"',
