      ru: 'Основа глагола + 기로 하다 → V-기로 하다  ·  가다 → 가기로 하다  ·  먹다 → 먹기로 하다  ·  운동하다 → 운동하기로 하다  ·  принятое решение → V-기로 했어요  ·  решение не делать → V-지 않기로 하다  ·  форма не зависит от 받침',
