    similar: {
      pattern: 'A-아/어 보이다 ↔ A-(으)ㄴ 것 같다',
      note: {
        ko: '"A-아/어 보이다"와 "A-(으)ㄴ 것 같다"는 모두 확실하게 단정하지 않고 자신의 판단을 말할 수 있지만 초점이 달라요. "피곤해 보여요."는 얼굴이나 표정처럼 눈에 보이는 모습을 근거로 "피곤한 인상을 준다"는 뜻이에요. 반면 "피곤한 것 같아요."는 외모뿐 아니라 말투, 행동, 상황 등 여러 근거를 바탕으로 "아마 피곤한 것 같다"고 추측할 수 있어요. 즉, 겉모습에서 직접 받은 인상을 말할 때는 "A-아/어 보이다", 좀 더 넓은 근거로 추측하거나 판단할 때는 "A-(으)ㄴ 것 같다"가 자연스러워요.',
        uz: '"A-아/어 보이다" va "A-(으)ㄴ 것 같다" ikkalasi ham qat’iy tasdiqlamasdan fikr bildirishga yordam beradi, ammo ularning urg‘usi boshqacha. "피곤해 보여요." yuz yoki tashqi ko‘rinishga qarab "charchaganga o‘xshaydi" degani. "피곤한 것 같아요." esa tashqi ko‘rinishdan tashqari gapirish usuli, harakat yoki vaziyatga qarab umumiy taxminni bildirishi mumkin. Shuning uchun ko‘rinishga asoslangan taassurotda "A-아/어 보이다", kengroq taxminda esa "A-(으)ㄴ 것 같다" ishlatiladi.',
        en: '"A-아/어 보이다" and "A-(으)ㄴ 것 같다" can both soften a judgment, but their focus is different. "피곤해 보여요." specifically describes an impression obtained from visible appearance, such as someone\'s face or expression. "피곤한 것 같아요." can be a broader inference based on appearance, behavior, speech, or circumstances. Use A-아/어 보이다 for a direct visual impression and A-(으)ㄴ 것 같다 for a more general judgment or guess.',
        ru: '"A-아/어 보이다" и "A-(으)ㄴ 것 같다" позволяют выражать мнение без категоричного утверждения, но отличаются оттенком. "피곤해 보여요." описывает впечатление именно от внешнего вида — лица или выражения. "피곤한 것 같아요." может быть более общим предположением на основании внешности, поведения, речи или ситуации. Поэтому для непосредственного зрительного впечатления естественно A-아/어 보이다, а для более общего предположения — A-(으)ㄴ 것 같다.',
      },
    },

