        en: '"N처럼[같이]" and "N 같은 N" both express resemblance, but they play different grammatical roles. In "모델처럼 키가 커요.", 모델처럼 modifies the following description and means "tall like a model." In "모델 같은 사람이에요.", 모델 같은 directly modifies the noun 사람. Use N처럼/같이 when describing an action or state, and N 같은 N when directly modifying a following noun.',
        ru: '"N처럼[같이]" и "N 같은 N" выражают сходство, но выполняют разные функции. В "모델처럼 키가 커요." форма 모델처럼 относится к последующему описанию и означает «высокий, как модель». В "모델 같은 사람이에요." форма 모델 같은 непосредственно определяет существительное 사람. Поэтому N처럼/같이 обычно используется перед описанием действия или состояния, а N 같은 N — для определения следующего существительного.',
