    isActive: true,

    summary: {
      ko: '"A-게"는 형용사가 나타내는 상태나 성질을 뒤의 행동이 이루어지는 방식으로 바꾸어 표현할 때 사용해요. "짧다 → 짧게 자르다", "예쁘다 → 예쁘게 꾸미다", "조용하다 → 조용하게 말하다"처럼 형용사를 "어떻게?"에 대답하는 표현으로 만들어요.',
      uz: '"A-게" sifat bildirgan holat yoki xususiyatni keyingi harakatning qanday bajarilishini ko‘rsatadigan shaklga aylantiradi. Masalan, "짧다 → 짧게 자르다", "예쁘다 → 예쁘게 꾸미다", "조용하다 → 조용하게 말하다".',
      en: '"A-게" changes an adjective into an expression describing how an action is performed. For example, 짧다 becomes 짧게 in "짧게 자르다," 예쁘다 becomes 예쁘게 in "예쁘게 꾸미다," and 조용하다 becomes 조용하게 in "조용하게 말하다."',
      ru: '"A-게" превращает прилагательное в выражение, описывающее способ выполнения действия. Например: "짧다 → 짧게 자르다", "예쁘다 → 예쁘게 꾸미다", "조용하다 → 조용하게 말하다".',
    },

