    similar: {
      pattern: 'A/V-(으)ㄹ지 모르겠다 ↔ A/V-(으)ㄹ 것 같다',
      note: {
        ko: '"A/V-(으)ㄹ지 모르겠다"와 "A/V-(으)ㄹ 것 같다"는 모두 확실하지 않은 상황에서 사용할 수 있지만 화자의 판단 정도가 달라요. "월세가 비쌀지 모르겠어요."는 월세가 비싼지 싼지 아직 판단할 정보가 부족해서 어느 쪽인지 모르겠다는 뜻이에요. 반면 "월세가 비쌀 것 같아요."는 확실하지는 않지만 현재 가진 정보나 느낌을 바탕으로 비쌀 가능성이 더 높다고 추측하는 표현이에요. 즉, 어느 쪽인지 판단하기 어렵다면 "-(으)ㄹ지 모르겠다", 한쪽 가능성을 어느 정도 예상하고 있다면 "-(으)ㄹ 것 같다"가 자연스러워요.',
        uz: '"A/V-(으)ㄹ지 모르겠다" va "A/V-(으)ㄹ 것 같다" ikkalasi ham noaniqlikni bildiradi, lekin taxmin darajasi boshqacha. "월세가 비쌀지 모르겠어요." ijaraning qimmat yoki arzonligini aniqlash uchun ma’lumot yetarli emasligini bildiradi. "월세가 비쌀 것 같아요." esa aniq bo‘lmasa ham, mavjud ma’lumotga qarab qimmat bo‘lish ehtimoli yuqori deb taxmin qilishdir.',
        en: '"A/V-(으)ㄹ지 모르겠다" and "A/V-(으)ㄹ 것 같다" both deal with uncertainty, but the speaker\'s judgment is different. "월세가 비쌀지 모르겠어요." means that the speaker does not have enough information to know whether the rent will be expensive. "월세가 비쌀 것 같아요." means that the speaker has some reason to think the rent will probably be expensive. Use -(으)ㄹ지 모르겠다 when the outcome is genuinely unclear, and -(으)ㄹ 것 같다 when you are leaning toward one possibility.',
        ru: '"A/V-(으)ㄹ지 모르겠다" и "A/V-(으)ㄹ 것 같다" оба связаны с неопределённостью, но степень предположения разная. "월세가 비쌀지 모르겠어요." означает, что информации недостаточно, чтобы понять, дорогая аренда или нет. "월세가 비쌀 것 같아요." означает, что говорящий, хотя и не уверен, всё же предполагает, что аренда будет дорогой. Если трудно выбрать между возможностями, естественно -(으)ㄹ지 모르겠다; если есть склонность к одному варианту — -(으)ㄹ 것 같다.',
      },
    },

