        ru: '❌ Не используйте -(으)ㄹ지 모르겠다 для уже точно известного факта. Если в договоре указано, что аренда составляет 800 000 вон, нужно сказать ✅ "월세가 80만 원이에요", а не "월세가 80만 원일지 모르겠어요".',
