    isActive: true,

    summary: {
      ko: '"A/V-기는 하지만"은 앞의 사실을 인정하면서, 뒤에서 그 사실과 반대되거나 예상과 다른 내용을 덧붙일 때 사용해요. "집이 넓기는 하지만 월세가 비싸요", "역이 가깝기는 하지만 주변이 시끄러워요"처럼 장점과 단점, 또는 서로 대비되는 두 가지 사실을 함께 말할 때 아주 유용해요.',
      uz: '"A/V-기는 하지만" avvalgi holatni tan olgan holda, keyin unga qarama-qarshi yoki kutilganidan boshqa ma’lumotni qo‘shishda ishlatiladi. Masalan, "집이 넓기는 하지만 월세가 비싸요", "역이 가깝기는 하지만 주변이 시끄러워요".',
      en: '"A/V-기는 하지만" acknowledges that the first statement is true and then adds contrasting or unexpected information. It is useful for describing both sides of a situation, as in "집이 넓기는 하지만 월세가 비싸요."',
      ru: '"A/V-기는 하지만" используется, когда говорящий признаёт первое утверждение, но затем добавляет противоположную или неожиданную информацию. Например: "집이 넓기는 하지만 월세가 비싸요."',
    },

