    isActive: true,

    summary: {
      ko: '"A/V-기 때문에, N(이)기 때문에"는 어떤 일이나 상태가 뒤에 나오는 결과의 이유나 원인임을 설명할 때 사용해요. "주변이 조용하기 때문에 살기 좋아요", "지하철역이 가깝기 때문에 교통이 편리해요", "새 아파트이기 때문에 시설이 깨끗해요"처럼 이유를 비교적 분명하게 설명할 수 있어요.',
      uz: '"A/V-기 때문에, N(이)기 때문에" biror harakat yoki holat keyingi natijaning sababi ekanini tushuntirishda ishlatiladi. Masalan, "주변이 조용하기 때문에 살기 좋아요", "지하철역이 가깝기 때문에 교통이 편리해요", "새 아파트이기 때문에 시설이 깨끗해요".',
      en: '"A/V-기 때문에, N(이)기 때문에" is used to explain that an action, state, or identity is the reason or cause of the result that follows. For example, "주변이 조용하기 때문에 살기 좋아요" and "새 아파트이기 때문에 시설이 깨끗해요."',
      ru: '"A/V-기 때문에, N(이)기 때문에" используется для объяснения причины или основания последующего результата. Например: "주변이 조용하기 때문에 살기 좋아요", "새 아파트이기 때문에 시설이 깨끗해요".',
    },

