        uz: '❌ "주변이 조용해서기 때문에 좋아요" deyilmaydi. "-기 때문에" o‘zakka to‘g‘ridan-to‘g‘ri qo‘shiladi: ✅ "주변이 조용하기 때문에 좋아요".',
        en: '❌ Do not say "주변이 조용해서기 때문에 좋아요". Attach -기 때문에 directly to the stem: ✅ "주변이 조용하기 때문에 좋아요".',
        ru: '❌ Нельзя говорить "주변이 조용해서기 때문에 좋아요". Присоединяйте -기 때문에 непосредственно к основе: ✅ "주변이 조용하기 때문에 좋아요".',
