        uz: '❌ "학생 때문에 할인을 받아요" va "학생이기 때문에 할인을 받아요" bir xil emas. Agar chegirma sababi o‘zingizning talaba ekaningiz bo‘lsa, ✅ "학생이기 때문에 할인을 받아요" deyiladi.',
        en: '❌ "학생 때문에 할인을 받아요" and "학생이기 때문에 할인을 받아요" do not mean the same thing. If being a student is the reason for the discount, use ✅ "학생이기 때문에 할인을 받아요".',
        ru: '❌ "학생 때문에 할인을 받아요" и "학생이기 때문에 할인을 받아요" означают разное. Если причиной скидки является ваш статус студента, правильно ✅ "학생이기 때문에 할인을 받아요".',
