        en: '❌ If the event causing the result has already been completed, omitting the needed past tense can change the meaning. If the move happened last week, ✅ "지난주에 이사했기 때문에..." is natural.',
        ru: '❌ Если событие-причина уже завершилось, отсутствие прошедшего времени может изменить смысл. Если переезд был на прошлой неделе, естественно ✅ "지난주에 이사했기 때문에...".',
