        uz: '❌ Boshlang‘ich bosqichda "-기 때문에"dan keyin to‘g‘ridan-to‘g‘ri buyruq yoki taklif shaklini qo‘llamaslik yaxshi. Bunday vaziyatda sababni alohida gap bilan aytish yoki boshqa sabab grammatikasini ishlatish tabiiyroq.',
        en: '❌ At the beginner level, avoid directly following -기 때문에 with an imperative or proposal. It is safer to separate the reason into another sentence or use a reason expression appropriate for commands and suggestions.',
        ru: '❌ На начальном этапе лучше не соединять "-기 때문에" непосредственно с приказом или предложением. Естественнее разделить причину на отдельное предложение или использовать другую причинную конструкцию.',
