        uz: '❌ "주차하는가 어려워요" noto‘g‘ri. Bu grammatikada ✅ "주차하기가 어려워요" ishlatiladi.',
        en: '❌ Do not say "주차하는가 어려워요". Use ✅ "주차하기가 어려워요".',
