    isActive: true,

    summary: {
      ko: '"V-(으)ㄴ 적(이) 있다/없다"는 과거부터 지금까지 어떤 행동을 해 본 경험이 있는지 없는지를 말할 때 사용해요. "한국에 가 본 적이 있어요", "공연장에서 사진을 찍은 적이 없어요"처럼 경험의 유무를 나타내요.',
      uz: '"V-(으)ㄴ 적(이) 있다/없다" o‘tmishdan hozirgacha biror ishni qilib ko‘rgan tajriba bor yoki yo‘qligini bildiradi. Masalan, "한국에 가 본 적이 있어요", "공연장에서 사진을 찍은 적이 없어요".',
      en: '"V-(으)ㄴ 적(이) 있다/없다" expresses whether someone has ever had the experience of doing something. For example, "한국에 가 본 적이 있어요" or "공연장에서 사진을 찍은 적이 없어요."',
      ru: '"V-(으)ㄴ 적(이) 있다/없다" используется, чтобы сказать, был ли у человека когда-либо опыт выполнения какого-либо действия: "한국에 가 본 적이 있어요", "공연장에서 사진을 찍은 적이 없어요".',
    },

    tags: [
      {
        ko: '초중급',
        uz: 'Boshlang‘ich-o‘rta',
        en: 'Elementary-intermediate',
        ru: 'Начально-средний',
      },
      { ko: '경험', uz: 'Tajriba', en: 'Experience', ru: 'Опыт' },
      { ko: '과거', uz: 'O‘tmish', en: 'Past', ru: 'Прошедшее' },
    ],

    explanation: {
      ko: '"V-(으)ㄴ 적(이) 있다/없다"는 과거의 어느 시점에 어떤 행동을 해 본 경험이 있는지 없는지를 말하는 표현이에요. 여기서 "적"은 과거에 있었던 경험이나 일을 뜻해요. "한국에서 살아 본 적이 있어요."라고 하면 지금 한국에 살고 있다는 뜻이 아니라, 과거에 한국에서 살아 본 경험이 있다는 뜻이에요. 반대로 "한국에서 살아 본 적이 없어요."는 지금까지 한 번도 그런 경험이 없다는 뜻이에요. 동사 어간에 받침이 있으면 "-은 적", 받침이 없으면 "-ㄴ 적"을 사용해요. "먹다 → 먹은 적", "읽다 → 읽은 적", "가다 → 간 적", "보다 → 본 적"처럼 만들어요. ㄹ 받침 동사는 ㄹ이 없어지고 "-ㄴ"이 붙어서 "살다 → 산 적", "만들다 → 만든 적"이 돼요. 실제 회화에서는 새로운 경험을 말할 때 "V-아/어 보다"와 결합한 "V-아/어 본 적이 있다"가 아주 자주 사용돼요. "한복을 입어 본 적이 있어요?", "한국 음식을 만들어 본 적이 있어요?"처럼 말할 수 있어요. 하지만 반드시 "-아/어 보다"가 필요한 것은 아니에요. "지갑을 잃어버린 적이 있어요", "수업에 늦은 적이 있어요"처럼 실제로 발생했던 사건도 그대로 표현할 수 있어요. 이 문법은 보통 정확히 언제 있었는지보다 경험의 존재 여부에 초점이 있어요. 그래서 "어제 영화를 본 적이 있어요"처럼 특정한 한 번의 과거 사건을 단순 보고하는 상황에서는 보통 "어제 영화를 봤어요"가 더 자연스러워요. 14과처럼 예절이나 문화 차이를 이야기할 때는 "한국에서 예절 때문에 실수한 적이 있어요", "공연장에서 휴대폰이 울린 적이 있어요"처럼 자신의 경험을 이야기하는 데 유용해요.',
      uz: '"V-(으)ㄴ 적(이) 있다/없다" o‘tmishdagi biror vaqtda ma’lum ishni qilgan tajriba bor yoki yo‘qligini bildiradi. Bu yerda "적" o‘tmishdagi tajribani anglatadi. "한국에서 살아 본 적이 있어요." hozir Koreyada yashayapman degani emas, balki avval Koreyada yashab ko‘rganman degani. Fe’l o‘zagida 받침 bo‘lsa "-은 적", bo‘lmasa "-ㄴ 적" ishlatiladi: "먹다 → 먹은 적", "가다 → 간 적". ㄹ bilan tugagan fe’llarda ㄹ tushadi: "살다 → 산 적". Kundalik nutqda "V-아/어 본 적이 있다" ham juda ko‘p ishlatiladi: "한복을 입어 본 적이 있어요?" Bu grammatika aniq vaqtga emas, tajribaning mavjud yoki mavjud emasligiga urg‘u beradi.',
      en: '"V-(으)ㄴ 적(이) 있다/없다" describes whether an experience has occurred at some point in the past. 적 refers to a past experience or occasion. "한국에서 살아 본 적이 있어요." does not mean that the speaker currently lives in Korea; it means that the speaker has had the experience of living there before. If the verb stem has a final consonant, use -은 적, as in "먹다 → 먹은 적". If there is no final consonant, use -ㄴ 적, as in "가다 → 간 적". ㄹ-final verbs drop ㄹ before ㄴ: "살다 → 산 적". In conversation, the pattern frequently combines with V-아/어 보다: "한복을 입어 본 적이 있어요?" However, this is not required. Actual events can also be expressed directly, as in "지갑을 잃어버린 적이 있어요." The construction focuses on whether an experience has ever occurred rather than exactly when it happened.',
      ru: '"V-(으)ㄴ 적(이) 있다/없다" показывает, был ли у человека когда-либо определённый опыт в прошлом. Слово 적 обозначает прошлый случай или опыт. "한국에서 살아 본 적이 있어요." означает, что человек когда-то жил в Корее, а не обязательно живёт там сейчас. После основы с 받침 используется -은 적: "먹다 → 먹은 적", без 받침 — -ㄴ 적: "가다 → 간 적". У глаголов на ㄹ этот согласный выпадает: "살다 → 산 적". В разговорной речи часто встречается сочетание с V-아/어 보다: "한복을 입어 본 적이 있어요?" Однако оно не обязательно: можно сказать и "지갑을 잃어버린 적이 있어요." Главный акцент делается на наличии или отсутствии опыта.',
    },

    conjugationRule: {
      ko: '동사 어간 + -(으)ㄴ 적이 있다/없다  ·  받침 있음 → -은 적: 먹다 → 먹은 적  ·  받침 없음 → -ㄴ 적: 가다 → 간 적  ·  ㄹ 받침 → ㄹ 탈락 + ㄴ: 살다 → 산 적  ·  경험 강조 → V-아/어 본 적이 있다/없다',
      uz: 'Fe’l o‘zagi + -(으)ㄴ 적이 있다/없다  ·  받침 bor → -은 적: 먹다 → 먹은 적  ·  받침 yo‘q → -ㄴ 적: 가다 → 간 적  ·  ㄹ tushadi + ㄴ: 살다 → 산 적  ·  tajribani ta’kidlash → V-아/어 본 적이 있다/없다',
      en: 'Verb stem + -(으)ㄴ 적이 있다/없다  ·  final consonant → -은 적: 먹다 → 먹은 적  ·  no final consonant → -ㄴ 적: 가다 → 간 적  ·  ㄹ-final → drop ㄹ + ㄴ: 살다 → 산 적  ·  experiential emphasis → V-아/어 본 적이 있다/없다',
      ru: 'Основа глагола + -(으)ㄴ 적이 있다/없다  ·  с 받침 → -은 적: 먹다 → 먹은 적  ·  без 받침 → -ㄴ 적: 가다 → 간 적  ·  ㄹ выпадает + ㄴ: 살다 → 산 적  ·  акцент на опыте → V-아/어 본 적이 있다/없다',
    },

