        ko: '"V-(으)면 안 되다"와 "V-지 마세요"는 모두 어떤 행동을 하지 못하게 할 수 있지만 초점이 달라요. "여기서 사진을 찍으면 안 돼요"는 이 장소의 규칙상 사진 촬영이 금지되어 있다는 설명에 가까워요. "여기서 사진을 찍지 마세요"는 지금 상대방에게 직접 사진을 찍지 말라고 요청하거나 지시하는 느낌이 더 강해요. 규칙·예절을 설명할 때는 "-(으)면 안 되다"가 매우 자연스러워요.',
        uz: '"V-(으)면 안 되다" qoidaga ko‘ra taqiqni tushuntiradi, "V-지 마세요" esa suhbatdoshga bevosita qilmaslikni aytadi.',
