    summary: {
      ko: '"A-아지다/어지다"는 어떤 사람이나 사물의 상태가 이전과 다르게 변했음을 나타내요. "날씨가 따뜻해졌어요", "한국 생활에 익숙해졌어요", "친구가 많아졌어요"처럼 과거와 현재를 비교하면서 상태의 변화를 말할 때 사용해요.',
      uz: '"A-아지다/어지다" odam yoki narsaning holati oldingidan o‘zgarganini bildiradi. Masalan, "날씨가 따뜻해졌어요", "한국 생활에 익숙해졌어요", "친구가 많아졌어요".',
      en: '"A-아지다/어지다" expresses a change from one state to another. It is used when comparing a previous state with a new one, as in "날씨가 따뜻해졌어요", "한국 생활에 익숙해졌어요", and "친구가 많아졌어요."',
      ru: '"A-아지다/어지다" выражает изменение состояния по сравнению с прошлым. Например: "날씨가 따뜻해졌어요", "한국 생활에 익숙해졌어요", "친구가 많아졌어요".',
    },

