    explanation: {
      ko: '"A-아지다/어지다"는 형용사가 나타내는 상태가 시간이 지나면서 다른 상태로 변했음을 표현하는 문법이에요. 단순히 "지금 어떻다"라고 말하는 것이 아니라 "전에는 그렇지 않았는데 지금은 그렇게 되었다"라는 변화의 의미가 포함돼요. 예를 들어 "한국 생활에 익숙해요."는 현재 한국 생활이 익숙하다는 상태만 말해요. 하지만 "한국 생활에 익숙해졌어요."라고 하면 처음에는 익숙하지 않았지만 시간이 지나면서 이제 익숙한 상태가 되었다는 뜻이에요. 그래서 과거와 현재의 차이를 설명하거나 사람, 도시, 생활, 능력 등이 어떻게 변했는지를 이야기할 때 아주 자주 사용해요. 만드는 방법은 형용사의 일반적인 "-아/어" 활용 뒤에 "-지다"를 붙이는 것과 같아요. 마지막 모음이 ㅏ 또는 ㅗ이면 보통 "-아지다"를 사용해서 "작다 → 작아지다", "좋다 → 좋아지다", "많다 → 많아지다"처럼 만들어요. 그 밖의 모음은 "-어지다"를 사용해서 "길다 → 길어지다", "넓다 → 넓어지다"처럼 만들어요. "하다" 형용사는 "해지다"가 되어 "조용하다 → 조용해지다", "편리하다 → 편리해지다", "익숙하다 → 익숙해지다"처럼 활용해요. 기본 활용의 불규칙도 그대로 적용돼요. "춥다 → 추워지다", "어렵다 → 어려워지다", "예쁘다 → 예뻐지다", "크다 → 커지다", "바쁘다 → 바빠지다"처럼 말해요. 특히 15과에서는 인생이나 도시의 변화를 설명하기 때문에 "서울이 많이 복잡해졌어요", "교통이 편리해졌어요", "고향에 건물이 많아졌어요", "한국어 실력이 좋아졌어요" 같은 문장이 중요해요. 이 표현은 누가 일부러 변화를 만들었다는 것보다 결과적으로 상태가 달라졌다는 사실에 초점을 두는 경우가 많아요. 예를 들어 "방이 깨끗해졌어요."는 방이 이전보다 깨끗한 상태가 되었다는 변화에 초점이 있어요. 누가 방을 깨끗하게 만들었다는 행동을 강조하려면 "방을 깨끗하게 청소했어요"처럼 다른 표현을 사용할 수 있어요.',
      uz: '"A-아지다/어지다" sifat bildirgan holat vaqt o‘tishi bilan boshqa holatga o‘zgarganini ko‘rsatadi. Bu shunchaki hozirgi holatni emas, oldingi holatdan hozirgi holatga o‘tishni bildiradi. Masalan, "한국 생활에 익숙해요." faqat hozir Koreyadagi hayotga ko‘nikkanlikni bildiradi. "한국 생활에 익숙해졌어요." esa avval ko‘nikmagan bo‘lsangiz ham, vaqt o‘tishi bilan ko‘nikib qolganingizni bildiradi. ㅏ yoki ㅗ dan keyin odatda "-아지다": "작다 → 작아지다", "좋다 → 좋아지다". Boshqa unlilardan keyin "-어지다": "길다 → 길어지다", "넓다 → 넓어지다". 하다 bilan tugagan sifatlarda "해지다": "조용하다 → 조용해지다", "익숙하다 → 익숙해지다". Oddiy noto‘g‘ri tuslanish qoidalari ham saqlanadi: "춥다 → 추워지다", "예쁘다 → 예뻐지다", "크다 → 커지다". Bu grammatika odamning hayoti, qobiliyati, shahar yoki atrof-muhit qanday o‘zgarganini tushuntirishda juda ko‘p ishlatiladi.',
      en: '"A-아지다/어지다" expresses that a state described by an adjective has changed over time. It does more than describe the current condition: it implies that the previous state was different. For example, "한국 생활에 익숙해요." simply says that Korean life is familiar now, whereas "한국 생활에 익숙해졌어요." means that it was unfamiliar before but has become familiar over time. The construction follows normal -아/어 conjugation and adds -지다. Adjectives with ㅏ or ㅗ generally take -아지다, as in "작다 → 작아지다" and "좋다 → 좋아지다". Other vowels generally take -어지다, as in "길다 → 길어지다" and "넓다 → 넓어지다". 하다 adjectives become 해지다: "조용하다 → 조용해지다", "편리하다 → 편리해지다", and "익숙하다 → 익숙해지다". Normal irregular conjugations also apply: "춥다 → 추워지다", "어렵다 → 어려워지다", "예쁘다 → 예뻐지다", and "크다 → 커지다". This construction is especially useful for describing changes in life, skills, cities, and living conditions.',
      ru: '"A-아지다/어지다" показывает, что состояние, выраженное прилагательным, со временем изменилось. Это не просто описание нынешнего состояния: форма подразумевает отличие от прошлого. Например, "한국 생활에 익숙해요." означает, что сейчас жизнь в Корее привычна, а "한국 생활에 익숙해졌어요." — что раньше она была непривычной, но со временем человек привык. Конструкция строится по обычным правилам -아/어 с добавлением -지다. После ㅏ или ㅗ обычно используется -아지다: "작다 → 작아지다", "좋다 → 좋아지다". В остальных случаях — -어지다: "길다 → 길어지다", "넓다 → 넓어지다". Прилагательные на 하다 дают 해지다: "조용하다 → 조용해지다", "익숙하다 → 익숙해지다". Сохраняются и обычные неправильные изменения: "춥다 → 추워지다", "예쁘다 → 예뻐지다", "크다 → 커지다".',
    },

    conjugationRule: {
      ko: '형용사 어간 + -아지다/-어지다 → 상태 변화  ·  ㅏ/ㅗ → -아지다: 작다 → 작아지다, 좋다 → 좋아지다  ·  그 외 → -어지다: 길다 → 길어지다, 넓다 → 넓어지다  ·  하다 → 해지다: 익숙하다 → 익숙해지다  ·  불규칙 활용도 적용: 춥다 → 추워지다, 예쁘다 → 예뻐지다, 크다 → 커지다',
      uz: 'Sifat o‘zagi + -아지다/-어지다 → holat o‘zgarishi  ·  ㅏ/ㅗ → -아지다: 작다 → 작아지다  ·  boshqa unlilar → -어지다: 길다 → 길어지다  ·  하다 → 해지다: 익숙하다 → 익숙해지다  ·  noto‘g‘ri tuslanish ham qo‘llanadi',
      en: 'Adjective stem + -아지다/-어지다 → change of state  ·  ㅏ/ㅗ → -아지다: 작다 → 작아지다  ·  other vowels → -어지다: 길다 → 길어지다  ·  하다 → 해지다: 익숙하다 → 익숙해지다  ·  normal irregular conjugations still apply',
      ru: 'Основа прилагательного + -아지다/-어지다 → изменение состояния  ·  ㅏ/ㅗ → -아지다: 작다 → 작아지다  ·  остальные → -어지다: 길다 → 길어지다  ·  하다 → 해지다: 익숙하다 → 익숙해지다  ·  сохраняются правила неправильного спряжения',
    },

    conjugations: [
      { base: '좋다 + 아지다', result: '좋아지다' },
      { base: '작다 + 아지다', result: '작아지다' },
      { base: '많다 + 아지다', result: '많아지다' },
      { base: '길다 + 어지다', result: '길어지다' },
      { base: '넓다 + 어지다', result: '넓어지다' },
      { base: '춥다 + 어지다', result: '추워지다' },
      { base: '예쁘다 + 어지다', result: '예뻐지다' },
      { base: '크다 + 어지다', result: '커지다' },
      { base: '바쁘다 + 아지다', result: '바빠지다' },
      { base: '조용하다 + 여지다', result: '조용해지다' },
      { base: '편리하다 + 여지다', result: '편리해지다' },
      { base: '익숙하다 + 여지다', result: '익숙해지다' },
    ],

