    similar: {
      pattern: 'N 대신 ↔ N 말고',
      note: {
        ko: '"N 대신"과 "N 말고"는 모두 한 대상을 선택하지 않고 다른 대상을 선택할 때 함께 보일 수 있지만 의미의 초점이 달라요. "커피 대신 차를 마셨어요."는 커피가 차로 대체되었다는 의미가 분명해요. "커피 말고 차 주세요."는 커피를 제외하고 차를 달라는 선택의 의미가 중심이에요. 실제로 한 대상이 다른 대상의 역할이나 자리를 대신한다는 점을 강조하면 "대신"이 더 자연스러워요.',
        uz: '"N 대신" almashtirishga urg‘u beradi, "N 말고" esa Nni chiqarib tashlab boshqa narsani tanlashga urg‘u beradi.',
        en: '"N 대신" emphasizes substitution, while "N 말고" mainly excludes N and chooses something else. If one item or person actually takes another\'s place, 대신 is particularly natural.',
        ru: '"N 대신" подчёркивает замену одного другим, а "N 말고" прежде всего исключает N из выбора. Если один объект действительно занимает место другого, 대신 особенно естественно.',
      },
    },

