        ko: '"V-아/어 주다"는 상대방을 위해 어떤 행동을 해 준다는 수혜 의미가 중심이에요. "문을 열어 주세요", "사진을 찍어 주세요"처럼 같은 장소에서 바로 할 수 있는 행동에도 사용할 수 있어요. 반면 "V-아다/어다 주다"는 다른 장소에서 행동을 한 다음 그 결과를 가져오거나 사람·물건을 이동시키는 느낌이 강해요. "도서관에서 책을 빌려다 주세요", "물을 떠다 주세요", "집까지 데려다 주세요"처럼 이동이 포함된 상황에서 특히 자연스러워요.',
        uz: '"V-아/어 주다" birov uchun ish qilishga urg‘u beradi. "V-아다/어다 주다" esa boshqa joyda ishni bajarib, natijani olib kelish yoki odam/narsani yetkazishga urg‘u beradi.',
        en: '"V-아/어 주다" mainly means doing something for someone and does not require movement. "V-아다/어다 주다" more strongly suggests performing an action elsewhere and fetching, bringing, or transporting the result.',
