    summary: {
      ko: '"V-(으)ㄹ 뻔하다"는 어떤 일이 실제로 일어나지는 않았지만 거의 일어날 정도로 위험하거나 가까운 상황이었다는 뜻이에요. "비행기를 놓칠 뻔했어요", "계단에서 넘어질 뻔했어요"처럼 아슬아슬하게 피한 사고나 문제를 이야기할 때 사용해요.',
      uz: '"V-(으)ㄹ 뻔하다" biror hodisa aslida sodir bo‘lmagan, lekin deyarli sodir bo‘layozganini bildiradi. Masalan, "비행기를 놓칠 뻔했어요", "넘어질 뻔했어요".',
      en: '"V-(으)ㄹ 뻔하다" means that something almost happened but ultimately did not. It is especially common for near misses and dangerous situations, as in "비행기를 놓칠 뻔했어요."',
      ru: '"V-(으)ㄹ 뻔하다" означает, что событие почти произошло, но в итоге не случилось. Особенно часто используется для опасных ситуаций: "비행기를 놓칠 뻔했어요".',
    },

