    explanation: {
      ko: '"V-아/어 있다"는 어떤 행동이 끝난 다음 그 행동으로 만들어진 상태가 현재까지 계속되고 있음을 나타내는 표현이에요. 예를 들어 "문이 열렸어요."는 문이 열리는 변화가 일어났다는 사실에 초점이 있어요. "문이 열려 있어요."는 문이 열린 뒤 지금도 열린 상태라는 뜻이에요. 그래서 이 표현은 행동 자체보다 현재 눈에 보이는 결과 상태를 묘사할 때 아주 유용해요. 만드는 방법은 동사를 일반적인 "-아/어"형으로 활용한 뒤 "있다"를 붙이는 거예요. "앉다 → 앉아 있다", "서다 → 서 있다", "눕다 → 누워 있다", "붙다 → 붙어 있다"처럼 사용할 수 있어요. 문이나 전등처럼 누군가의 행동으로 상태가 변하는 대상은 피동형과 함께 자주 사용돼요. "열다 → 열리다 → 열려 있다", "닫다 → 닫히다 → 닫혀 있다", "켜다 → 켜지다 → 켜져 있다", "끄다 → 꺼지다 → 꺼져 있다", "놓다 → 놓이다 → 놓여 있다"처럼 말해요. 17과의 분실물 설명에서는 특히 유용해요. "가방 앞에 작은 주머니가 달려 있어요.", "손잡이에 빨간 리본이 묶여 있어요.", "옆면에 이름이 쓰여 있어요.", "지갑 안에 학생증이 들어 있어요."처럼 물건의 현재 모습을 자세하게 설명할 수 있기 때문이에요. "-고 있다"와의 차이도 중요해요. 기본적으로 "-고 있다"는 어떤 행동이 진행 중임을 나타내는 경우가 많고, "-아/어 있다"는 완료된 행동의 결과 상태를 나타내요. "문이 열리고 있어요."는 문이 지금 열리는 과정이고, "문이 열려 있어요."는 이미 열려서 그 상태가 유지되고 있다는 뜻이에요. 다만 한국어에는 "옷을 입고 있다", "안경을 쓰고 있다"처럼 착용 상태를 "-고 있다"로 표현하는 동사도 있기 때문에 모든 상태를 무조건 "-아/어 있다"로 만들 수 있는 것은 아니에요.',
      uz: '"V-아/어 있다" harakat tugagandan keyin hosil bo‘lgan holat hozirgacha saqlanib turganini bildiradi. "문이 열렸어요." eshikning ochilgan voqeasiga urg‘u beradi. "문이 열려 있어요." esa eshik ochilib, hozir ham ochiq ekanini bildiradi. Fe’lning "-아/어" shakliga "있다" qo‘shiladi: "앉다 → 앉아 있다", "서다 → 서 있다", "눕다 → 누워 있다". Eshik yoki chiroq kabi narsalarda passiv shakllar bilan ko‘p ishlatiladi: "열리다 → 열려 있다", "닫히다 → 닫혀 있다", "켜지다 → 켜져 있다". Yo‘qolgan narsani tasvirlashda "리본이 묶여 있어요", "이름이 쓰여 있어요", "학생증이 들어 있어요" kabi gaplar juda foydali. "-고 있다" ko‘pincha jarayonni, "-아/어 있다" esa tugagan harakat natijasidagi holatni bildiradi.',
      en: '"V-아/어 있다" describes a state that continues after an action has been completed. "문이 열렸어요." focuses on the change in which the door opened, while "문이 열려 있어요." means that the door has opened and remains open now. Form the construction with the normal -아/어 form followed by 있다: "앉다 → 앉아 있다", "서다 → 서 있다", "눕다 → 누워 있다", and "붙다 → 붙어 있다". With objects whose state changes through another action, passive or change-of-state verbs frequently appear: "열리다 → 열려 있다", "닫히다 → 닫혀 있다", "켜지다 → 켜져 있다", "꺼지다 → 꺼져 있다", and "놓이다 → 놓여 있다". This is especially useful for lost-item descriptions: "리본이 묶여 있어요", "이름이 쓰여 있어요", or "학생증이 들어 있어요". Compare this with -고 있다, which often focuses on an action currently in progress. "문이 열리고 있어요." means that the door is in the process of opening, whereas "문이 열려 있어요." describes the already-open state. However, not every maintained state uses -아/어 있다; expressions such as "옷을 입고 있다" use -고 있다.',
      ru: '"V-아/어 있다" описывает состояние, сохраняющееся после завершения действия. "문이 열렸어요." подчёркивает сам факт открытия двери, а "문이 열려 있어요." означает, что дверь уже открылась и сейчас остаётся открытой. Конструкция строится с формой -아/어 и 있다: "앉다 → 앉아 있다", "서다 → 서 있다", "눕다 → 누워 있다", "붙다 → 붙어 있다". Для предметов, состояние которых изменяется из-за внешнего действия, часто используются пассивные формы: "열리다 → 열려 있다", "닫히다 → 닫혀 있다", "켜지다 → 켜져 있다", "꺼지다 → 꺼져 있다", "놓이다 → 놓여 있다". Это особенно удобно для описания потерянных вещей: "리본이 묶여 있어요", "이름이 쓰여 있어요", "학생증이 들어 있어요". В отличие от этого, -고 있다 часто обозначает процесс, происходящий сейчас.',
    },

    conjugationRule: {
      ko: '동사 -아/어형 + 있다 → V-아/어 있다  ·  ㅏ/ㅗ → -아 있다: 앉다 → 앉아 있다  ·  그 외 → -어 있다: 붙다 → 붙어 있다  ·  불규칙 활용 적용: 눕다 → 누워 있다  ·  상태 변화·피동 동사와 자주 결합: 열리다 → 열려 있다, 닫히다 → 닫혀 있다, 켜지다 → 켜져 있다, 놓이다 → 놓여 있다  ·  완료된 행동의 결과 상태가 유지됨',
      uz: 'Fe’lning -아/어 shakli + 있다  ·  ㅏ/ㅗ → -아 있다  ·  boshqalar → -어 있다  ·  noto‘g‘ri tuslanish ham qo‘llanadi  ·  passiv va holat o‘zgarish fe’llari bilan ko‘p ishlatiladi',
      en: 'Verb -아/어 form + 있다  ·  ㅏ/ㅗ → -아 있다  ·  other vowels → -어 있다  ·  normal irregular conjugation applies  ·  common with passive and change-of-state verbs  ·  expresses a maintained result after completion',
      ru: 'Форма глагола -아/어 + 있다  ·  ㅏ/ㅗ → -아 있다  ·  остальные → -어 있다  ·  сохраняются неправильные изменения  ·  часто сочетается с пассивными глаголами и глаголами изменения состояния',
    },

