    summary: {
      ko: '"V-(으)ㄴ 지"는 어떤 행동이나 사건이 일어난 뒤 지금까지 시간이 얼마나 지났는지 말할 때 사용해요. "한국에 온 지 6개월이 되었어요", "한국어를 공부한 지 1년 됐어요"처럼 보통 시간 표현과 "되다"를 함께 사용해요.',
      uz: '"V-(으)ㄴ 지" biror harakat yoki voqea sodir bo‘lganidan hozirgacha qancha vaqt o‘tganini bildiradi. Masalan, "한국에 온 지 6개월이 되었어요", "한국어를 공부한 지 1년 됐어요".',
      en: '"V-(으)ㄴ 지" expresses how much time has passed since an action or event occurred. It is commonly used with a duration and 되다, as in "한국에 온 지 6개월이 되었어요."',
      ru: '"V-(으)ㄴ 지" показывает, сколько времени прошло с момента какого-либо действия или события. Обычно используется с периодом времени и 되다: "한국에 온 지 6개월이 되었어요".',
    },

